async function run(input, tools) {
  const sheet = input && input.settings && input.settings.sales_sheet;
  const out = { today_rows: [] };
  if (!sheet) return out;

  const res = await tools.sheets.read({ sheet });
  const rows = (res && res.rows) || [];

  const now = new Date();
  const today = now.getFullYear() + "-" + String(now.getMonth() + 1).padStart(2, "0") + "-" + String(now.getDate()).padStart(2, "0");

  const norm = (v) => String(v == null ? "" : v).trim().slice(0, 10);
  const toNum = (v) => {
    if (typeof v === "number") return v;
    const n = parseFloat(String(v == null ? "" : v).replace(/[^0-9.\-]/g, ""));
    return isNaN(n) ? 0 : n;
  };

  out.today_rows = rows
    .filter((r) => norm(r.Date !== undefined ? r.Date : r.date) === today)
    .map((r) => ({
      date: norm(r.Date !== undefined ? r.Date : r.date),
      amount: toNum(r.Amount !== undefined ? r.Amount : r.amount),
    }));

